<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useI18n } from 'vue-i18n'
import { api, json, money, number } from '../api'
import type { Product } from '../types'
import { useApp } from '../stores/app'
import Results from '../components/Results.vue'
import ExportDialog from '../components/ExportDialog.vue'
import Icon from '../components/Icon.vue'
const { t, locale } = useI18n(); const route = useRoute(); const router = useRouter(); const app = useApp(); const product = ref<Product>(); const selectedRevision = ref(-1); const busy = ref(false); const showExport = ref(false); const fullImage = ref('')
const evaluation = computed(() => product.value?.revisions[selectedRevision.value < 0 ? product.value.revisions.length - 1 : selectedRevision.value])
const date = (s: string) => new Intl.DateTimeFormat(locale.value, { dateStyle:'medium',timeStyle:'short' }).format(new Date(s))
async function load() { try { product.value = await api<Product>(`/products/${route.params.id}`); selectedRevision.value = -1 } catch(e) { app.report(e) } }
onMounted(load)
watch(() => route.params.id, load)
async function action(name: string) { if (!product.value) return; busy.value = true; app.clear(); try { const p = await api<Product>(`/products/${product.value.id}/${name}`,json('POST',{ version:product.value.version })); if (name === 'duplicate') await router.push(`/products/${p.id}`); product.value = p; selectedRevision.value = -1; app.success(t(name === 'recalculate' ? 'recalculatedSuccess' : name === 'archive' ? 'archivedSuccess' : name === 'restore' ? 'restoredSuccess' : 'savedSuccess')) } catch(e) { app.report(e) } finally { busy.value = false } }
async function addImage(event: Event) { if (!product.value) return; const files = Array.from((event.target as HTMLInputElement).files || []); if (files.length + product.value.images.length > 5 || files.some(f => f.size > 5*1024*1024 || !['image/jpeg','image/png','image/webp'].includes(f.type))) { app.report(new Error(t('invalidImage'))); return } busy.value = true; try { for (const file of files) { const form = new FormData(); form.set('file',file); form.set('version',String(product.value.version)); product.value = await api<Product>(`/products/${product.value.id}/images`,{method:'POST',body:form}) } } catch(e) { app.report(e) } finally { busy.value = false; (event.target as HTMLInputElement).value = '' } }
async function removeImage(id: string) { if (!product.value) return; busy.value = true; try { product.value = await api<Product>(`/products/${product.value.id}/images/${id}`,json('DELETE',{version:product.value.version})) } catch(e) { app.report(e) } finally { busy.value = false } }
</script>
<template><RouterLink to="/" class="text-link back-link"><Icon name="back" :size="17" />{{ t('back') }}</RouterLink><div v-if="!product" class="loading-state">{{ app.error ? t('missingProduct') : t('loading') }}</div><template v-else><div class="page-heading detail-heading"><div><span class="eyebrow">{{ product.input.sku || t(product.input.category) }}<span v-if="product.archived" class="badge">{{ t('archived') }}</span></span><h1>{{ product.input.name }}</h1><p>{{ t(product.input.category) }} · {{ t('updated') }} {{ date(product.updatedAt) }}</p></div><div class="heading-actions"><button class="btn secondary" @click="showExport = true"><Icon name="download" />{{ t('export') }}</button><RouterLink :to="`/products/${product.id}/edit`" class="btn primary"><Icon name="edit" />{{ t('edit') }}</RouterLink></div></div><div class="detail-toolbar"><div><button class="text-link" :disabled="busy" @click="action('duplicate')"><Icon name="copy" :size="16" />{{ t('duplicate') }}</button><button class="text-link" :disabled="busy" @click="action(product.archived ? 'restore' : 'archive')"><Icon name="archive" :size="16" />{{ t(product.archived ? 'restore' : 'archive') }}</button></div><button class="text-link" :disabled="busy" @click="action('recalculate')"><Icon name="refresh" :size="16" />{{ t('recalculate') }}</button></div><div class="history-strip"><div><Icon name="clock" /><div><strong>{{ t('history') }}</strong><small>{{ t('frozen') }}</small></div></div><select v-model="selectedRevision" :aria-label="t('history')"><option :value="-1">{{ t('revision') }} {{ product.revisions.length }} · {{ t('updated') }}</option><option v-for="(rev,i) in product.revisions.slice(0,-1)" :key="rev.id" :value="i">{{ t('revision') }} {{ i+1 }} · {{ date(rev.createdAt) }}</option></select></div><Results v-if="evaluation" :evaluation="evaluation" />
 <section class="panel form-panel"><div class="section-title"><span class="section-icon"><Icon name="box" /></span><div><h3>{{ t('basic') }}</h3><p>{{ t('savedOn') }} {{ evaluation ? date(evaluation.createdAt) : '' }}</p></div></div><div v-if="evaluation" class="detail-inputs"><div v-for="key in ['cost','price','orders','fixed','packaging','targetMargin'] as const" :key="key"><span>{{ t(key) }}</span><strong>{{ key === 'orders' ? number(evaluation.input[key]) : key === 'targetMargin' ? evaluation.input[key] + '%' : money(evaluation.input[key]) }}</strong></div></div><p v-if="product.input.notes" class="product-notes">{{ product.input.notes }}</p></section>
 <section v-if="product.competitors?.length" class="panel form-panel"><h3>{{ t('competitors') }}</h3><div class="table-wrap"><table><thead><tr><th>{{ t('platform') }}</th><th>{{ t('shop') }}</th><th>{{ t('price') }}</th><th>{{ t('sales') }}</th><th>{{ t('rating') }}</th></tr></thead><tbody><tr v-for="c in product.competitors" :key="c.id"><td>{{ c.platform }}</td><td><a v-if="c.url" :href="c.url" target="_blank" rel="noopener noreferrer" class="text-link">{{ c.shop }}<Icon name="arrowUp" :size="14" /></a><span v-else>{{ c.shop }}</span></td><td>{{ money(c.price) }}</td><td>{{ number(c.sales) }}</td><td>{{ number(c.rating,1) }}</td></tr></tbody></table></div></section>
 <section class="panel form-panel"><div class="section-title"><span class="section-icon"><Icon name="image" /></span><div><h3>{{ t('screenshots') }} <small>{{ product.images.length }} / 5</small></h3><p>{{ t('screenshotsHint') }}</p></div></div><div class="image-grid"><div v-for="im in product.images" :key="im.id" class="image-card"><button class="image-preview" :aria-label="im.name" @click="fullImage = im.url"><img :src="im.thumbnail" :alt="im.name" /></button><button class="icon-btn image-delete" :disabled="busy" :aria-label="t('remove')" @click="removeImage(im.id)"><Icon name="close" :size="16" /></button></div><label v-if="product.images.length < 5 && !busy" class="image-upload"><Icon name="plus" /><span>{{ t('addImages') }}</span><input type="file" multiple accept="image/jpeg,image/png,image/webp" @change="addImage" /></label></div></section><ExportDialog v-if="showExport" :ids="[product.id]" @close="showExport = false" /><Teleport to="body"><div v-if="fullImage" class="modal-backdrop image-lightbox" @click="fullImage = ''"><button class="icon-btn" :aria-label="t('close')"><Icon name="close" :size="28" /></button><img :src="fullImage" :alt="product.input.name" @click.stop /></div></Teleport></template></template>
